# Generated by Claude
"""
Build the ARA public release: June 2021 - August 2026.

Merges the previously published January release with the new 2026 export into
one continuous series, under freshly generated random pond IDs.

What this script does
---------------------
  - replaces the internal pond identifier with a random public one, via a
    key held outside this repository
  - drops direct identifiers: farmer name, GPS location, village
  - generalises fish source to a category
  - rewrites references to other ponds inside free-text notes so they use
    published identifiers, and redacts any it cannot resolve
  - removes notes flagged in review as containing identifying detail

Identifier patterns, note fragments and redaction spans are held in the
private config beside the key, not here. Publishing the patterns that
recognise internal identifiers narrows the space an attacker has to search,
which is the same class of mistake as publishing a hash salt.

Fails closed throughout: an unmapped pond aborts the run, and any redaction
that fires aborts it too, so an unrecognised identifier is caught before
publication rather than after.
"""

import csv
import re
import sys
from datetime import datetime
from pathlib import Path

import private_config as _private   # not in this repository

BASE = Path("./source_data")   # gitignored; never commit
OLD = BASE / "previous_release"
KEY = Path("../private/pond_key.csv")   # NOT in this repository
OUT = Path(".")

DROP = {
    "Farmer", "Location", "Village", "Sr. No", "parsed_date",
    # Staff names are not published (from v3.1.0).
    "Observer", "Added by", "Logged by", "Data verified by",
    # README states financial figures are excluded; these were retained as
    # empty headers in v2.0.0, which contradicted that claim on its face.
    "How much did the farmer pay for the stocked fish and shrimp? (in INR)",
    "Earnings from the fish/shrimp sale (in INR)",
}
FISH_SRC = "Fish source (e.g. hatchery name)"

# Note fragments and identifier patterns live in the private config beside the
# key. They are not defined here: a fragment naming a farmer contains the name
# it exists to remove, and the identifier patterns describe the internal ID
# schema precisely enough to shrink an attacker's search space.
REMOVE_SNIPPETS = _private.REMOVE_SNIPPETS
PREFIXED = _private.PREFIXED
BARE = _private.BARE
BARE_STOP = _private.BARE_STOP
REDACT_SPANS = _private.REDACT_SPANS   # place names and similar, by exact span

# Staff names that may appear in free-text notes, replaced on publication.
# Held in the private config for the same reason as the note fragments.
# Required: a build without it could publish a name from a note.
STAFF_NAMES = set(_private.STAFF_NAMES)

# Retraction (v3.1.0). Fabricated water quality data was found in Nellore, so
# every Nellore measurement on or after the Winkler changeover is published
# separately, as retracted. See README and
# https://www.fishwelfareinitiative.org/post/data-issues
RETRACT_REGION = "Nellore"
RETRACT_FROM = datetime(2024, 11, 1)
RETRACTED_FILE = "water_quality_nellore_retracted.csv"


def fish_category(v):
    t = (v or "").lower().strip()
    if not t or t in ("none", "na", "n/a", "unknown"):
        return ""
    if re.search(r"\b(own|his own|their own|self)\b", t):
        return "Own pond"
    if "hatcher" in t:
        return "Hatchery"
    if "nurser" in t or "nursary" in t or "nursury" in t:
        return "Nursery pond"
    if "market" in t:
        return "Local market"
    if re.search(r"local (farmer|fisher)|farmers|fisheries|locally|other farmer", t):
        return "Local farmers"
    if re.search(r"\bfrom\b|\bnamed\b", t) or len(t.split()) <= 3:
        return "Individual supplier"
    return "Other / unspecified"


def load_key():
    fwd, old2new, suffix = {}, {}, {}
    for r in csv.DictReader(open(KEY, newline="", encoding="utf-8-sig")):
        i = r["internal_pond_id"].strip()
        n = r["public_pond_id"].strip()
        fwd[i] = n
        # every prior namespace maps forward, so a stale reference from any
        # earlier release is rewritten rather than published
        for col in ("v2_public_pond_id", "v1_public_pond_id_COMPROMISED"):
            o = (r.get(col) or "").strip()
            if o:
                old2new[o] = n
        suffix.setdefault(i.split("-")[-1], n)
    return fwd, old2new, suffix


# Matches identifiers from ANY previous release namespace, so a stale
# reference in a note is remapped rather than published.
OLD_PUBLIC = re.compile(r"\b(?:pond|ara\d?)_[0-9a-f]{8}\b")

# Monetary content. Notes containing any of this are removed in full: the
# structured INR columns were dropped, but the same figures had been entered
# as prose, so emptying the columns alone achieved nothing.
MONEY = re.compile(
    r"(rupees|\brs\.?\s*\d|₹|@\s*\d+\s*(per|/)\s*kg|\b\d[\d,]{4,}\s*(rupees|rs)"
    r"|\bper\s*kg\b|\blakh\b|\bcrore\b|\bcost[:\s]*\d|\bprice[:\s]*\d)", re.I)

REDACTIONS = []   # every fail-closed redaction, so the run can be blocked
MONEY_REMOVED = []


def clean_text(v, suffix, old2new=None):
    """Blank removed notes; rewrite every pond reference to the new public ID.

    Both identifier paths FAIL CLOSED: a code that is not in the key is
    redacted, never passed through. v2.0.0 shipped three internal codes
    because this path returned unrecognised codes unchanged while the
    prefixed path redacted them -- the same function, opposite postures.

    Matching is case-insensitive. v2.0.0 matched uppercase only, so a
    mixed-case code was never tested against the key at all.
    """
    if not isinstance(v, str) or not v.strip():
        return v
    for name in STAFF_NAMES:
        v = re.sub(rf"\b{re.escape(name)}\b", "our field staff member", v)
    for snip in REMOVE_SNIPPETS:
        if snip in v:
            return ""
    if MONEY.search(v):
        MONEY_REMOVED.append(v[:80])
        return ""
    for span in REDACT_SPANS:
        if span in v:
            v = v.replace(span, "")
            REDACTIONS.append(("span", span))
    if old2new:
        v = OLD_PUBLIC.sub(lambda m: old2new.get(m.group(0), m.group(0)), v)

    def _lookup(m):
        code = m.group(1)
        if code.upper() in BARE_STOP or code[:-1].upper() in BARE_STOP:
            return m.group(0)
        hit = suffix.get(code.upper())
        if hit:
            return hit
        REDACTIONS.append(("unmapped code", code))
        return "[pond reference removed]"

    v = PREFIXED.sub(_lookup, v)
    return BARE.sub(_lookup, v)


def region_of(internal):
    return "Eluru" if internal.startswith("WG-") else (
        "Nellore" if internal.startswith("NL-") else "Unknown")


def read_published(path, old2new):
    """Old release: map compromised pond_id -> internal -> new id."""
    rows, unmapped = [], set()
    for r in csv.DictReader(open(path, newline="", encoding="utf-8-sig")):
        pid = (r.get("pond_id") or "").strip()
        new = old2new.get(pid)
        if pid and not new:
            unmapped.add(pid)
            continue
        r["pond_id"] = new
        rows.append(r)
    return rows, unmapped


def read_export(path, pond_col, fwd):
    rows, unmapped = [], set()
    for r in csv.DictReader(open(path, newline="", encoding="utf-8-sig")):
        raw = (r.get(pond_col) or "").strip()
        new = fwd.get(raw)
        if raw and not new:
            unmapped.add(raw)
            continue
        out = {"pond_id": new, "region": region_of(raw)}
        for k, val in r.items():
            if k == pond_col or k in DROP:
                continue
            out[k] = val
        rows.append(out)
    return rows, unmapped


def merge(pub, new, dedupe_within, keycols):
    """Union, preferring the new export where a record appears in both.

    `dedupe_within` also removes exact re-entries inside a single source --
    the stocking export contains one event logged twice, differing only in
    its `Created at` timestamp. Left off for the pond registry, where a
    repeated pond_id is a real data question rather than a re-entry.
    """
    def sig(r):
        return tuple((r.get(c) or "").strip() for c in keycols)

    seen = {sig(r) for r in new}
    out = new + [r for r in pub if sig(r) not in seen]

    if not dedupe_within:
        return out, 0
    kept, seen2, dropped = [], set(), 0
    for r in out:
        s = sig(r)
        if s in seen2:
            dropped += 1
            continue
        seen2.add(s)
        kept.append(r)
    return kept, dropped


def write(path, rows, suffix, old2new):
    if not rows:
        return 0
    fields = []
    for r in rows:
        for k in r:
            if k not in fields and k not in DROP:
                fields.append(k)
    fields = ["pond_id", "region"] + [f for f in fields if f not in ("pond_id", "region")]
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")
        w.writeheader()
        for r in rows:
            out = {}
            for k in fields:
                v = r.get(k)
                if k == FISH_SRC:
                    v = fish_category(v)
                elif isinstance(v, str):
                    v = clean_text(v, suffix, old2new)
                out[k] = v
            w.writerow(out)
    return len(rows)


def split_retracted(rows):
    """Separate retracted rows. Fails closed on an unparseable date in the
    retracted region, since a silent parse failure would leave it published."""
    keep, retracted = [], []
    for r in rows:
        if r.get("region") != RETRACT_REGION:
            keep.append(r)
            continue
        raw = (r.get("Date of data collection") or "").strip()
        try:
            d = datetime.strptime(raw, "%m/%d/%Y")
        except ValueError:
            sys.exit(f"FATAL: unparseable date {raw!r} in a {RETRACT_REGION} "
                     "water quality row; cannot apply the retraction.")
        (retracted if d >= RETRACT_FROM else keep).append(r)
    return keep, retracted


def main():
    fwd, old2new, suffix = load_key()
    print(f"key: {len(fwd)} ponds, {len(old2new)} old->new mappings\n")

    problems = []
    specs = [
        # name, old file, new export, pond column, dedupe key, dedupe-within-source
        ("water_quality.csv", OLD / "water_quality.csv",
         BASE / "export-1383-measurements.csv", "Pond ID",
         # Type included: two visits can share a date when time is unrecorded
         # as 00:00, and they are distinct measurements, not duplicates.
         ["pond_id", "Date of data collection", "Time of data collection", "Type"],
         True),
        ("stocking_harvest.csv", OLD / "stocking_harvest.csv",
         BASE / "export-1384-stock-harvest-events.csv", "Pond",
         ["pond_id", "Event date", "Type"], True),
        ("enrolled_ponds.csv", OLD / "enrolled_ponds_2026-02-02.csv",
         BASE / "export-1385-ponds.csv", "Pond ID", ["pond_id"], False),
        ("dropouts.csv", OLD / "dropouts.csv",
         BASE / "export-1386-drop-outs.csv", "Pond",
         ["pond_id", "Date of drop out"], True),
    ]

    for name, oldp, newp, pcol, keys, dw in specs:
        pub, u1 = read_published(oldp, old2new)
        new, u2 = read_export(newp, pcol, fwd)
        if u1 or u2:
            problems.append((name, sorted(u1 | u2)[:10]))
        rows, dropped = merge(pub, new, dw, keys)
        if name == "water_quality.csv":
            rows, retracted = split_retracted(rows)
            nr = write(OUT / "data" / RETRACTED_FILE, retracted, suffix, old2new)
            print(f"{RETRACTED_FILE:24} retracted={nr}")
        n = write(OUT / "data" / name, rows, suffix, old2new)
        extra = f"  (dropped {dropped} re-entry)" if dropped else ""
        print(f"{name:24} published={len(pub):6}  new={len(new):5}  merged={n:6}{extra}")

    if problems:
        print("\nUNMAPPED PONDS:")
        for nm, ps in problems:
            print(f"  {nm}: {ps}")
        sys.exit("FATAL: unmapped ponds; refusing to publish.")

    print(f"\nWritten to {OUT/'data'}")
    if MONEY_REMOVED:
        print(f"\nNotes removed for monetary content: {len(MONEY_REMOVED)}")

    # A redaction means an identifier was found that the key could not
    # resolve. The output is safe -- it was redacted -- but something is
    # unaccounted for, and that should be understood before publishing
    # rather than discovered afterwards.
    if REDACTIONS:
        from collections import Counter
        counts = Counter(REDACTIONS)
        accepted = getattr(_private, "ACCEPTED_REDACTIONS", set())
        unexpected = {k: n for k, n in counts.items() if k[1] not in accepted}

        print("\nREDACTIONS FIRED:")
        for (kind, val), n in counts.items():
            mark = " (reviewed)" if val in accepted else "  <-- NEW"
            print(f"  {kind}: {val!r} x{n}{mark}")

        if unexpected:
            sys.exit(f"\nFATAL: {len(unexpected)} unreviewed redaction(s). "
                     "The output is safe -- each was redacted -- but an "
                     "identifier appeared that nobody has looked at. Review "
                     "them, then add to ACCEPTED_REDACTIONS to proceed.")
        print("  all reviewed and accepted; proceeding")


if __name__ == "__main__":
    main()
